import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_div_relu_kernel(const float* input, float* output, float divisor, int num_elements) {
    const int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < num_elements) {
        float val = input[index] / divisor;
        output[index] = val > 0 ? val : 0.01f * val;
    }
}

torch::Tensor fused_div_relu_cuda(torch::Tensor input, float divisor) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int threads_per_block = 256;
    const int num_blocks = (num_elements + threads_per_block - 1) / threads_per_block;

    fused_div_relu_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        divisor,
        num_elements
    );

    return output;
}
"""

fused_op_cpp_source = "torch::Tensor fused_div_relu_cuda(torch::Tensor input, float divisor);"

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=["fused_div_relu_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, divisor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.divisor = divisor

    def forward(self, x):
        x = self.conv(x)
        x = fused_op.fused_div_relu_cuda(x, self.divisor)
        return x
